/**
 * Response shapes for the demo API.
 *
 * TODO(TASK-001): replace with types generated by `make types` once the backend and
 * docs/API_CONTRACT.md exist. Until then the mock server in src/mocks returns exactly these shapes,
 * with every decimal serialised as a string, as it would arrive over JSON.
 */

export type Currency = 'INR';

/** A monetary amount: decimal string plus ISO 4217 code. Never a float. */
export interface Money {
  amount: string;
  currency: Currency;
}

export type NodeKind = 'anchor' | 'person';
export type NodeStatus = 'ACTIVE' | 'RESTRICTED' | 'DEFAULTED';

export interface ApiNode {
  id: string;
  kind: NodeKind;
  name: string;
  /** Occupation for a person, institution type for an anchor. */
  role: string;
  place: string;
  cluster: string;
  /** Credibility R, decimal string. */
  R: string;
  /** Vouch capacity C = max(0, R). */
  capacity: string;
  status: NodeStatus;
  /** Registered with no vouches, repayments or linked data yet. */
  coldStart: boolean;
  nullifier: string | null;
  joinedDay: number;
  settledLoans: number;
  sources: { aa: boolean; utility: boolean };
}

export interface ApiEdge {
  from: string;
  to: string;
  /** W_uv = C_u / |Out(u)|. */
  weight: string;
  createdDay: number;
  /** Loan this vouch currently backs; its capacity is locked until the loan closes. */
  lockedLoanId: string | null;
}

export type LoanStatus = 'APPLIED' | 'DISBURSED' | 'SETTLED' | 'DEFAULTED' | 'DECLINED';

export interface ApiLoan {
  id: string;
  borrower: string;
  principal: Money;
  emi: Money;
  purpose: string;
  status: LoanStatus;
  appliedDay: number;
  disbursedDay: number | null;
  dueDay: number | null;
  closedDay: number | null;
  /** Primary slash if this loan defaults. */
  delta0: string;
  /** Default recorded while the cluster circuit breaker was open; slash queued for review. */
  slashQueued: boolean;
}

export interface ApiVouchRequest {
  id: string;
  from: string;
  to: string;
  status: 'PENDING' | 'ACCEPTED' | 'DECLINED';
  day: number;
  note: string;
}

export type Contract = 'IdentityRegistry' | 'VouchHub' | 'LoanEscrow' | 'CircuitBreaker';

export interface ApiDelta {
  node: string;
  delta: string;
  k?: number;
}

export interface ApiEvent {
  id: string;
  seq: number;
  contract: Contract;
  name: string;
  tx: string;
  block: number;
  day: number;
  status: 'pending' | 'confirmed';
  summary: string;
  actors: string[];
  deltas: ApiDelta[];
}

export interface ApiCluster {
  id: string;
  name: string;
  members: string[];
  defaulted: number;
  tripped: boolean;
  queued: string[];
}

export interface ApiPath {
  nodes: string[];
  trust: string;
}

export interface ApiCashflow {
  meanIncome: Money;
  obligations: Money;
  proposedEmi: Money;
  debtService: Money;
  dscr: string;
  incomeCv: string;
  volatility: string;
  sCashflow: string;
}

export interface ApiAssessment {
  nodeId: string;
  rGraph: string;
  paths: ApiPath[];
  absorbed: number;
  cashflow: ApiCashflow | null;
  nSettled: number;
  inDegree: number;
  nData: number;
  completeness: string;
  mu: string;
  sigma2: string;
  sigma: string;
  /** Score_final, the lower confidence bound. */
  lcb: string;
  bandLow: string;
  bandHigh: string;
  limit: Money;
  requested: Money | null;
}

export interface ApiPenalty {
  node: string;
  k: number;
  delta: string;
  before: string;
  after: string;
}

export interface ApiCascade {
  id: string;
  loanId: string;
  defaulter: string;
  penalties: ApiPenalty[];
  queued: boolean;
  day: number;
}

export type StoryStep =
  | 'register'
  | 'request'
  | 'vouch'
  | 'apply'
  | 'approve'
  | 'advance'
  | 'outcome'
  | 'settled'
  | 'defaulted';

export interface Snapshot {
  version: number;
  day: number;
  block: number;
  nodes: Record<string, ApiNode>;
  edges: ApiEdge[];
  loans: ApiLoan[];
  requests: ApiVouchRequest[];
  events: ApiEvent[];
  clusters: ApiCluster[];
  assessments: Record<string, ApiAssessment>;
  borrowerId: string;
  voucherId: string;
  lenderId: string;
  story: StoryStep;
  lastCascade: ApiCascade | null;
}

export interface SimulateRequest {
  nodeId: string;
  monthlyIncome?: string;
  obligations?: string;
  principal?: string;
  aa?: boolean;
  utility?: boolean;
}

export interface SimulateResponse {
  assessment: ApiAssessment;
  /** DSCR at or above the 1.25 micro-lending threshold. */
  dscrHealthy: boolean;
  /** Monthly instalment on the simulated principal, if one was given. */
  emi: Money | null;
}

export interface DemoIdentity {
  rawId: string;
  name: string;
  district: string;
  occupation: string;
  yearOfBirth: string;
}

export interface RegisterResponse {
  node: ApiNode;
  nullifier: string;
  /** The nullifier already existed: re-registration resolved to the same record. */
  existing: boolean;
}
